useEffect(() => {
  if (busySince === null) return;
  const id = setInterval(() => {
    if (Date.now() - busySince > 45_000) {
      setStuckWarning(true);
      clearInterval(id);
    }
  }, 2_000);
  return () => clearInterval(id);
}, [busySince]);

